insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 2, 2, 'Na poziomie oczekiwań', 'Porządkuje wypowiedź, wyjaśnia potrzebne pojęcia i dostosowuje język oraz szczegółowość do rozmówcy i sytuacji.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'komunikacja' and i.sort_order = 2;
