insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 2, 2, 'Na poziomie oczekiwań', 'Porównuje wykonalne warianty według istotnych kryteriów i wskazuje główne ryzyka oraz ograniczenia.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 1;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 3, 3, 'Powyżej oczekiwań', 'W złożonej sprawie sprawdza kluczowe założenia, porównuje scenariusze i wskazuje działania ograniczające ryzyko.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 1;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 4, 4, 'Znacznie powyżej oczekiwań', 'Przy dużej niepewności ocenia odporność wariantów na zmianę założeń oraz określa warunki wyboru, korekty lub wycofania.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 1;
insert into public.competency_indicators (competency_id, sort_order, title) select id, 2, 'Podejmowanie decyzji (decyzyjność).' from public.competencies where code = 'podejmowanie_decyzji';
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 0, 0, 'Znacznie poniżej oczekiwań', 'Zwleka z rozstrzygnięciem pomimo dostępnych przesłanek albo podejmuje decyzję bez niezbędnych ustaleń lub poza zakresem uprawnień.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 2;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 1, 1, 'Poniżej oczekiwań', 'Podejmuje decyzje w typowych sprawach po przypomnieniu lub odkłada złożone rozstrzygnięcie bez wskazania brakujących przesłanek i terminu.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 2;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 2, 2, 'Na poziomie oczekiwań', 'Podejmuje i komunikuje uzasadnioną decyzję w czasie adekwatnym do sprawy. W razie potrzeby uzyskuje konsultację lub przekazuje sprawę zgodnie z uprawnieniami.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 2;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 3, 3, 'Powyżej oczekiwań', 'Terminowo rozstrzyga sprawy złożone na podstawie kluczowych informacji i określa przesłanki ponownej oceny decyzji.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 2;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 4, 4, 'Znacznie powyżej oczekiwań', 'W warunkach presji i niepewności dobiera tryb decyzji do jej skutków i odwracalności oraz określa warunki dalszych rozstrzygnięć.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 2;
insert into public.competency_indicators (competency_id, sort_order, title) select id, 3, 'Przyjmowanie odpowiedzialności za efekty podjętych
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 0, 0, 'Znacznie poniżej oczekiwań', 'Nie wyjaśnia skutków swojej decyzji lub pozostawia ujawnione konsekwencje bez reakcji w swoim zakresie.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 3;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 1, 1, 'Poniżej oczekiwań', 'Odnosi się do skutków po interwencji, lecz nie ustala dalszych działań albo nie sprawdza ich wykonania.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 3;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 2, 2, 'Na poziomie oczekiwań', 'Wyjaśnia przesłanki decyzji, monitoruje jej skutki i podejmuje potrzebną korektę w swoim zakresie.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 3;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 3, 3, 'Powyżej oczekiwań', 'W razie niekorzystnych skutków informuje zainteresowanych, inicjuje działania naprawcze i potwierdza ich wykonanie.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 3;
insert into public.competency_indicator_levels (indicator_id, level_index, points, label, description) select i.id, 4, 4, 'Znacznie powyżej oczekiwań', 'Przy decyzjach o szerokich konsekwencjach monitoruje skutki w dłuższym okresie i przekłada wnioski oraz rezultaty korekt na kolejne decyzje.' from public.competency_indicators i join public.competencies c on c.id = i.competency_id where c.code = 'podejmowanie_decyzji' and i.sort_order = 3;
